<script>
// ===========================
// 配置区：请在此处填写你的世界书信息
// ===========================
const TDHN_CONFIG = {
  wiFile: "一个呕吐的男人",        // 世界书名称（不含.json后缀）
  uidUserInfo: "12",         // 同担_user信息 条目UID
  uidVtuber: "11",           // 同担_虚拟主播 条目UID
  uidWeibo: "5",            // 同担_微博Bot 条目UID
  uidWechat: "4",           // 同担_微信 条目UID
  uidSettings: "13",         // 同担_设置 条目UID
};

// 当前选中的模式
let tdhnCurrentMode = null;

// ===== 漂浮粒子生成 =====
(function initParticles() {
  const container = document.getElementById('tdhn-particles');
  if (!container) return;
  const colors = ['rgba(88,166,255,0.4)', 'rgba(247,120,186,0.3)', 'rgba(63,185,80,0.25)', 'rgba(255,255,255,0.15)'];
  for (let i = 0; i < 18; i++) {
    const p = document.createElement('div');
    p.className = 'tdhn-particle';
    const size = Math.random() * 4 + 1.5;
    p.style.cssText = `
      width: ${size}px; height: ${size}px;
      left: ${Math.random() * 100}%;
      background: ${colors[Math.floor(Math.random() * colors.length)]};
      animation-duration: ${Math.random() * 12 + 10}s;
      animation-delay: ${Math.random() * 8}s;
      box-shadow: 0 0 ${size * 2}px ${colors[Math.floor(Math.random() * colors.length)]};
    `;
    container.appendChild(p);
  }
})();

// ===== 手风琴 =====
function tdhnToggleAcc(header) {
  const body = header.nextElementSibling;
  const isOpen = header.classList.contains('active');
  // 关闭所有
  document.querySelectorAll('.tdhn-acc-header.active').forEach(h => {
    h.classList.remove('active');
    h.nextElementSibling.classList.remove('open');
    h.nextElementSibling.style.padding = '0 18px';
  });
  if (!isOpen) {
    header.classList.add('active');
    body.classList.add('open');
  }
}

// ===== 卡片翻转 =====
function tdhnFlipCard(card) {
  card.classList.toggle('flipped');
}

// ===== 模式选择 =====
function tdhnSelectMode(mode) {
  tdhnCurrentMode = mode;
  const cardTD = document.getElementById('tdhn-card-tongdan');
  const cardVT = document.getElementById('tdhn-card-vtuber');
  const vtuberFields = document.getElementById('tdhn-vtuber-fields');
  const tag = document.getElementById('tdhn-mode-tag');

  cardTD.classList.remove('selected');
  cardVT.classList.remove('selected');

  if (mode === 'tongdan') {
    cardTD.classList.add('selected');
    vtuberFields.classList.remove('show');
    // 移除虚拟主播字段的required
    document.querySelectorAll('#tdhn-vtuber-fields input[required]').forEach(el => el.removeAttribute('required'));
    tag.textContent = '✓ 已选择：纯同担模式';
  } else {
    cardVT.classList.add('selected');
    vtuberFields.classList.add('show');
    const vtName = document.getElementById('tdhn-vt-name');
    if (vtName && !vtName.hasAttribute('required')) vtName.setAttribute('required', '');
    tag.textContent = '✓ 已选择：虚拟主播 + 同担模式';
  }
  tag.classList.add('show');
}

// ===== 辅助：转义管道符 =====
function tdhnEscape(str) {
  if (typeof str !== 'string') return str;
  return str.replace(/[|]/g, '\\$&');
}

// ===== 表单提交 =====
async function tdhnSubmitForm(event) {
  event.preventDefault();

  if (!tdhnCurrentMode) {
    if (typeof triggerSlash === 'function') {
      triggerSlash('/echo severity=warning 请先在上方选择身份模式（纯同担 / 虚拟主播+同担）');
    } else {
      alert('请先选择身份模式');
    }
    return;
  }

  const data = {
    mode: tdhnCurrentMode,
    weibo_name: document.getElementById('tdhn-wb-name').value.trim(),
    weibo_avatar: document.getElementById('tdhn-wb-avatar').value.trim(),
    weibo_bio: document.getElementById('tdhn-wb-bio').value.trim(),
    weibo_style: document.getElementById('tdhn-wb-style').value.trim(),
    alt_name: document.getElementById('tdhn-alt-name').value.trim(),
    alt_avatar: document.getElementById('tdhn-alt-avatar').value.trim(),
    alt_style: document.getElementById('tdhn-alt-style').value.trim(),
  };

  if (tdhnCurrentMode === 'vtuber') {
    data.vtuber_name = document.getElementById('tdhn-vt-name').value.trim();
    data.vtuber_avatar = document.getElementById('tdhn-vt-avatar').value.trim();
    data.vtuber_look = document.getElementById('tdhn-vt-look').value.trim();
    data.vtuber_style = document.getElementById('tdhn-vt-style').value.trim();
    data.vtuber_active = document.getElementById('tdhn-vt-active').value;
    data.vtuber_fame = document.getElementById('tdhn-vt-fame').value;
  }

  const jsonStr = JSON.stringify(data, null, 2);
  const f = TDHN_CONFIG.wiFile;

  if (typeof triggerSlash !== 'function') {
    alert('酒馆助手未开启，无法提交。');
    console.log('表单数据：', jsonStr);
    return;
  }

  try {
    // 写入user信息
    let cmd = `/setentryfield file="${f}" uid=${TDHN_CONFIG.uidUserInfo} field=content ${tdhnEscape(jsonStr)}`;

    // 控制虚拟主播条目
    if (tdhnCurrentMode === 'vtuber') {
      cmd += ` || /setentryfield file="${f}" uid=${TDHN_CONFIG.uidVtuber} field=disable false`;
    } else {
      cmd += ` || /setentryfield file="${f}" uid=${TDHN_CONFIG.uidVtuber} field=disable true`;
    }

    cmd += ` || /echo severity=success 档案已录入！可以选择下方的故事开场了。`;
    await triggerSlash(cmd);
  } catch (err) {
    console.error('提交失败:', err);
    triggerSlash('/echo severity=error 提交失败，请检查控制台');
  }
}

// ===== 微博Bot开关 =====
async function tdhnToggleWeibo(enabled) {
  if (typeof triggerSlash !== 'function') return;
  const disable = enabled ? 'false' : 'true';
  const label = enabled ? '已开启' : '已关闭';
  await triggerSlash(`/setentryfield file="${TDHN_CONFIG.wiFile}" uid=${TDHN_CONFIG.uidWeibo} field=disable ${disable} || /echo severity=info 微博Bot ${label}`);
}

// ===== 微信开关 =====
async function tdhnToggleWechat(enabled) {
  if (typeof triggerSlash !== 'function') return;
  const disable = enabled ? 'false' : 'true';
  const label = enabled ? '已开启' : '已关闭';
  await triggerSlash(`/setentryfield file="${TDHN_CONFIG.wiFile}" uid=${TDHN_CONFIG.uidWechat} field=disable ${disable} || /echo severity=info 微信文件传输助手 ${label}`);
}

// ===== 微信主题切换 =====
async function tdhnSwitchTheme(theme, btn) {
  document.querySelectorAll('.tdhn-theme-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  if (typeof triggerSlash !== 'function') return;
  const label = theme === 'day' ? '白天' : '夜晚';
  await triggerSlash(`/setentryfield file="${TDHN_CONFIG.wiFile}" uid=${TDHN_CONFIG.uidSettings} field=content ${theme} || /echo severity=info 微信主题已切换为 ${label} 模式`);
}

// ===== 开场白动态加载 =====
async function tdhnLoadOpenings() {
  const container = document.getElementById('tdhn-openings');
  if (!container) return;

  if (typeof getChatMessages !== 'function') {
    container.innerHTML = '<div class="tdhn-opening-empty">酒馆助手未开启，无法加载开场白列表。</div>';
    return;
  }

  try {
    const messages = await getChatMessages("0", { include_swipe: true });
    if (!messages || !messages.length || !messages[0].swipes || messages[0].swipes.length <= 1) {
      container.innerHTML = '<div class="tdhn-opening-empty">暂无其他开场白。请在角色卡中添加更多开场白。</div>';
      return;
    }

    const swipes = messages[0].swipes;
    for (let i = 1; i < swipes.length; i++) {
      const content = swipes[i];
      let title = `开场白 ${i}`;
      let desc = '点击开启故事。';

      const tMatch = content.match(/<!--\s*title:\s*(.*?)\s*-->/s);
      if (tMatch) title = tMatch[1].trim();
      const dMatch = content.match(/<!--\s*desc:\s*(.*?)\s*-->/s);
      if (dMatch) desc = dMatch[1].trim();

      const item = document.createElement('div');
      item.className = 'tdhn-opening-item';
      item.style.setProperty('--i', i - 1);
      item.innerHTML = `<h4>${title}</h4><p>${desc}</p>`;
      item.addEventListener('click', () => tdhnSwitchOpening(i, item));
      container.appendChild(item);
    }
  } catch (err) {
    console.error('加载开场白失败:', err);
    container.innerHTML = '<div class="tdhn-opening-empty" style="color:var(--accent-red);">加载失败，请检查控制台。</div>';
  }
}

async function tdhnSwitchOpening(swipeId, element) {
  if (element) {
    element.style.opacity = '0.5';
    element.style.pointerEvents = 'none';
  }
  try {
    await setChatMessages([{ message_id: 0, swipe_id: swipeId }]);
  } catch (err) {
    console.error('切换失败:', err);
    if (element) {
      element.style.opacity = '1';
      element.style.pointerEvents = 'auto';
    }
  }
}

// 页面加载完成后加载开场白
window.addEventListener('load', tdhnLoadOpenings);
</script>
</body>
</html>
